    original: "आतुरे व्यसने प्राप्ते दुर्भिक्षे शत्रुसङ्कटे ।\nराजद्वारे श्मशाने च यस्तिष्ठति स बान्धवः ।।",
    transliteration: "āture vyasane prāpte durbhikṣe śatrusaṅkaṭe ।\nrājadvāre śmaśāne ca yastiṣṭhati sa bāndhavaḥ ।।",
