    transliteration: "balaṃ vidyā ca viprāṇāṃ rājñāṃ sainyaṃ balaṃ tathā ।\nbalaṃ vittaṃ ca vaiśyānāṃ śūdrāṇāṃ pāricaryakam ।।",
    meaning: "Knowledge is the strength of the learned; an army is the strength of kings; wealth is the strength of the trading class; and service is the strength of labourers.",
