    original: "अध्वा जरा देहवतां पर्वतानां जलं जरा ।\nअमैथुनं जरा स्त्रीणां वस्त्राणामातपो जरा ।।",
    transliteration: "adhvā jarā dehavatāṃ parvatānāṃ jalaṃ jarā ।\namaithunaṃ jarā strīṇāṃ vastrāṇāmātapo jarā ।।",
    meaning: "Travel wears down the body over time, flowing water wears down mountains over time; deprivation ages a woman, and constant sun wears down cloth.",
    meaning_hi: "यात्रा शरीरधारियों को वृद्ध बना देती है, बहता जल पर्वतों को घिस देता है; संभोग से वंचित रहना स्त्रियों को क्षीण करता है, और धूप में रहना वस्त्रों को जीर्ण करती है।",
