    transliteration: "agnirdevo dvijātīnāṃ munīnāṃ hṛdi daivatam ।\npratimā svalpabuddhīnāṃ sarvatra samadarśinaḥ ।।",
    meaning: "Fire is divine to the twice-born, the inner self is divine to sages, an image is divine to the simple-minded — but the truly wise see the same divinity everywhere.",
    meaning_hi: "अग्नि द्विजों के लिए देवता है, मुनियों के लिए हृदय में स्थित परमात्मा ही देवता है, अल्पबुद्धि वालों के लिए मूर्ति देवता है — पर ज्ञानी सब में समान भाव से देखते हैं।",
