    original: "निःस्पृहो नाधिकारी स्यान् नाकामो मण्डनप्रियः ।\nनाविदग्धः प्रियं ब्रूयात्स्पष्टवक्ता न वञ्चकः ।।",
    transliteration: "niḥspṛho nādhikārī syān nākāmo maṇḍanapriyaḥ ।\nnāvidagdhaḥ priyaṃ brūyātspaṣṭavaktā na vañcakaḥ ।।",
    meaning: "One without desire has no wish for high office; one without passion takes no delight in adornment; one lacking refinement cannot speak sweetly; and a plain speaker is no deceiver.",
