    tradition: 'other',
    original: "राजपत्नी गुरोः पत्नी मित्रपत्नी तथैव च ।\nपत्नीमाता स्वमाता च पञ्चैता मातरः स्मृताः ।।",
    transliteration: "rājapatnī guroḥ patnī mitrapatnī tathaiva ca ।\npatnīmātā svamātā ca pañcaitā mātaraḥ smṛtāḥ ।।",
