    original: "पक्षिणः काकश्चण्डालः पशूनां चैव कुक्कुरः ।\nमुनीनां पापश्चण्डालः सर्वचाण्डालनिन्दकः ।।",
    transliteration: "pakṣiṇaḥ kākaścaṇḍālaḥ paśūnāṃ caiva kukkuraḥ ।\nmunīnāṃ pāpaścaṇḍālaḥ sarvacāṇḍālanindakaḥ ।।",
