    meaning: "Graciousness with one's own people, kindness toward strangers, firmness toward the wicked, warmth toward the good, dignity before the arrogant, honesty with the wise, courage before enemies, patience toward elders, and tact with others -- those who master this whole range of conduct are the ones who truly hold the world together.",
