    transliteration: "satsaṅgādbhavati hi sādhunā khalānāṃ sādhūnāṃ na hi khalasaṃgataḥ khalatvam ।\nāmodaṃ kusumabhavaṃ mṛdeva dhatte mṛdgandhaṃ nahi kusumāni dhārayanti ।।",
