    original: "त्यज दुर्जनसंसर्गं भज साधुसमागमम् ।\nकुरु पुण्यमहोरात्रं स्मर नित्यमनित्यतः ।।",
    transliteration: "tyaja durjanasaṃsargaṃ bhaja sādhusamāgamam ।\nkuru puṇyamahorātraṃ smara nityamanityataḥ ।।",
